<?php require_once 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $n=trim($_POST['name']??'');$em=trim($_POST['email']??'');$ph=trim($_POST['phone']??'');$m=trim($_POST['message']??''); if($n&&filter_var($em,FILTER_VALIDATE_EMAIL)&&$m){$s=$conn->prepare('INSERT INTO messages(name,email,phone,message) VALUES(?,?,?,?)');$s->bind_param('ssss',$n,$em,$ph,$m);$s->execute();$s->close();$msg='Your message has been sent successfully.';}else $msg='Please enter a valid name, email and message.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact</title><link rel="stylesheet" href="Styles/style.css"></head><body><?php nav(); ?><section class="section"><div class="section-title"><h2>Contact Us</h2><p><?=e(site_content('contact_address'))?></p><p><?=e(site_content('contact_phone'))?> · <?=e(site_content('contact_hours'))?></p></div><div class="card form-card"><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><form method="post"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field full"><label>Message</label><textarea name="message" rows="5" required></textarea></div></div><br><button class="btn" type="submit">Send Message</button></form></div></section><footer class="footer">© <?=date('Y')?> AmarDayal Clinic</footer></body></html>
